import json
data = json.load(open('/app/resources/treasury_bulletin_2024_12.json'))
elements = data['document']['elements']
# Look for elements with 'on-budget' or 'off-budget' or 'outlays'
for i, e in enumerate(elements):
    if isinstance(e, dict):
        content = str(e.get('content', ''))
        if 'on-budget' in content.lower() or 'off-budget' in content.lower() or 'outlay' in content.lower():
            if 'Commerce' in content:
                print(f'Element {i}:', content[:2000])
                break"
